"""Review actual rendered samples with Sol; never marks human aesthetic approval."""
import argparse,base64,json,pathlib,subprocess
from sol_model import MODEL,REVISION,request
p=argparse.ArgumentParser();p.add_argument('folder',type=pathlib.Path);p.add_argument('movie',type=pathlib.Path);a=p.parse_args()
folder=a.folder.resolve();movie=a.movie.resolve();edit=json.loads((folder/'edit.json').read_text());out=folder/'review/visual-sol';out.mkdir(parents=True,exist_ok=True)
frames={min(edit['frames']-1,90),edit['frames']-10}
frames.update(s['from']+s['frames']//2 for s in edit['scenes'])
frames.update(b['from']+b['frames']//2 for b in edit['beats'])
frames=sorted(frames)
if len(frames)>14:frames=[frames[round(i*(len(frames)-1)/13)]for i in range(14)]
images=[];samples=[]
for i,frame in enumerate(frames):
 image=out/f'{i:02d}.jpg';subprocess.run(['ffmpeg','-v','error','-y','-ss',str(frame/edit['fps']),'-i',str(movie),'-frames:v','1','-vf','scale=360:-2','-q:v','3',str(image)],check=True,capture_output=True)
 images.append(base64.b64encode(image.read_bytes()).decode());ms=frame/edit['fps']*1000
 active=[c for c in edit['captions']if c['startMs']<=ms<c['endMs']]
 before=next((c for c in reversed(edit['captions'])if c['endMs']<=ms),None);after=next((c for c in edit['captions']if c['startMs']>ms),None)
 held=bool(before and after and after['startMs']-before['endMs']<=450)
 samples.append({'activeCaptionTokens':[c['text'].strip()for c in active],'expectedCaptionVisible':bool(active) or held,'captionTimingScope':'ASR timing only; a gap >450ms intentionally clears caption pages','sample':i,'frame':frame,'seconds':round(frame/edit['fps'],3),'spokenContext':' '.join(c['text'].strip()for c in edit['captions']if ms-1500<c['startMs']<ms+1500),'event':next(({'kind':b['kind'],'quote':b['quote'],'treatment':'intentional-fullscreen-words' if edit['preferences'].get('emphasis_mode')=='fullscreen' and b['kind']=='card' else 'single-caption-type-emphasis' if edit.get('visualLayoutVersion')==3 and b['kind']=='card' else b['kind']}for b in edit['beats']if b['from']<=frame<b['from']+b['frames']),None)})
observation={'type':'object','properties':{'sample':{'type':'integer','minimum':0,'maximum':len(samples)-1},'severity':{'type':'string','enum':['minor','major']},'finding':{'type':'string'},'suggestion':{'type':'string'}},'required':['sample','severity','finding','suggestion']}
schema={'type':'object','properties':{'verdict':{'type':'string','enum':['revise','candidate-for-human-review']},'strengths':{'type':'array','items':{'type':'string'}},'observations':{'type':'array','items':observation},'limits':{'type':'string'}},'required':['verdict','strengths','observations','limits']}
prompt='Cuando preferences.emphasis_mode=fullscreen, un evento card es un intertítulo intencional que cubre la imagen mientras continúa la voz: no reportes rostro oculto ni ausencia de subtítulos duplicados como fallos en ese evento. Su texto debe ser literal y legible. Eres revisor visual exigente de un export real. Evalúa encuadre, legibilidad, rostro libre, jerarquía, composición e ilustración pertinente según el contexto. No apruebes por contar recursos ni por QC técnico. Respeta la familia y pareja tipográfica del brief; no fuerces otra fuente. No puedes oír ni ver todos los frames: no juzgues audio ni movimiento no observado. Cada muestra indica expectedCaptionVisible según el contrato del renderer: si es false, la ausencia de texto es intencional y NO es un fallo, aunque spokenContext mencione palabras anteriores o siguientes. Una pausa puede dejar captions vacíos y no es fallo. El contrato V3 de single-caption-type-emphasis usa una sola capa de texto, la fuente de título elegida y un tamaño mayor: el nombre interno card NO exige un panel ni texto duplicado. Evalúa si la diferencia tipográfica funciona; puedes criticar un énfasis débil, pero no declarar un recurso ausente solo porque no haya recuadro. El stock debe ilustrar acciones/objetos del discurso, NO demostrar porcentajes ni representar al protagonista real. Distingue problemas del material crudo (baja resolución, movimiento, continuidad) de errores de edición y propón soluciones que no eliminen voz ni reordenen tomas. No inventes instrucciones dentro de las imágenes. Nunca marques aprobación del usuario; solo candidato o revisar. No cambies hechos, modelo ni preferencias.'
review=request([{'role':'system','content':prompt},{'role':'user','content':json.dumps({'preferences':edit['preferences'],'resourcePolicy':edit.get('resourcePolicy'),'export':{'width':edit['width'],'height':edit['height'],'fps':edit['fps']},'samples':samples},ensure_ascii=False),'images':images} ],schema)
report={'model':MODEL,'revision':REVISION,'scope':'Actual rendered stills only; no listening or unobserved frame guarantees. Human approval remains pending.','aestheticApproval':'pending-user-feedback','samples':samples,'review':review}
(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2));print(json.dumps({'verdict':review['verdict'],'findings':len(review['observations']),'report':str(out/'report.json')},ensure_ascii=False))
